/**
 * Unit tests for Matchers.anyShort()
 */
public class Matchers_anyShort_TriageGen0Test {

    @Test
    public void testAnyShortReturnsZero() {
        // The implementation of anyShort() is:
        // return reportMatcher(Any.ANY).returnZero();
        // Since returnZero() for a short matcher is expected to return 0 (or the default value for short),
        // we verify the return value.

        short result = Matchers.anyShort();

        assertEquals((short) 0, result);
    }
}
